    43		if err != nil {
    44			return fmt.Errorf("v2 /main write failed: %w", err)
    45		}
    46	
    47		if err := s.writeCommittedFullTranscript(ctx, opts, sessionIndex); err != nil {
    48			return fmt.Errorf("v2 /full/current write failed: %w", err)
    49		}
    50	
    51		return nil
    52	}
