 901	// ReadCommitted reads a committed checkpoint's summary by ID from the entire/checkpoints/v1 branch.
 902	// Returns only the CheckpointSummary (paths + aggregated stats), not actual content.
 903	// Use ReadSessionContent to read actual transcript/prompts/context.
 904	// Returns nil, nil if the checkpoint doesn't exist.
 905	//
 906	// The storage format uses numbered subdirectories for each session (0-based):
 907	//
 908	//	<checkpoint-id>/
 909	//	├── metadata.json      # CheckpointSummary with sessions map
 910	//	├── 0/                 # First session
 911	//	│   ├── metadata.json  # Session-specific metadata
 912	//	│   └── full.jsonl     # Transcript
 913	//	├── 1/                 # Second session
 914	//	└── ...
 915	func (s *GitStore) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
 916		if err := ctx.Err(); err != nil {
 917			return nil, err //nolint:wrapcheck // Propagating context cancellation
 918		}
 919	
 920		ft, err := s.getFetchingTree(ctx)
 921		if err != nil {
 922			return nil, nil //nolint:nilnil,nilerr // No sessions branch means no checkpoint exists
 923		}
 924	
 925		checkpointPath := checkpointID.Path()
 926		checkpointTree, err := ft.Tree(checkpointPath)
 927		if err != nil {
 928			return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
 929		}
 930	
 931		// Read root metadata.json as CheckpointSummary (auto-fetches blob if needed)
 932		metadataFile, err := checkpointTree.File(paths.MetadataFileName)
 933		if err != nil {
 934			return nil, nil //nolint:nilnil,nilerr // metadata.json not found
 935		}
 936	
 937		content, err := metadataFile.Contents()
 938		if err != nil {
 939			return nil, fmt.Errorf("failed to read metadata.json: %w", err)
 940		}
